-- REVIEWS FOR NEW PROPERTIES
-- ============================================

INSERT INTO reviews (id, user_id, campsite_id, booking_id, rating, comment, cleanliness_rating, location_rating, value_rating, facilities_rating, helpful_count, created_at, updated_at) VALUES
-- Galway Bay Guesthouse reviews
('00000000-0000-0000-0000-000000009001', '00000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000201', '00000000-0000-0000-0000-000000008001', 5, 'Best B&B experience in Ireland! Mary is the most welcoming host and her breakfast is legendary. The sea view room was worth every penny.', 5, 5, 5, 5, 18, '2025-08-05', '2025-08-05'),
('00000000-0000-0000-0000-000000009002', '00000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000201', '00000000-0000-0000-0000-000000008002', 5, 'A real gem in Salthill. Walking distance to everything and Mary goes above and beyond for her guests.', 5, 5, 4, 5, 12, '2025-08-10', '2025-08-10'),
('00000000-0000-0000-0000-000000009003', '00000000-0000-0000-0000-000000000004', '00000000-0000-0000-0000-000000000201', '00000000-0000-0000-0000-000000008003', 5, 'Perfect for families! The kids loved the cozy atmosphere and we loved the quiet location. Breakfast was incredible.', 5, 5, 5, 4, 8, '2025-08-16', '2025-08-16'),
-- Wild Atlantic Glamping reviews
('00000000-0000-0000-0000-000000009004', '00000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000202', '00000000-0000-0000-0000-000000008101', 5, 'Romantic getaway perfection! The dome with hot tub overlooking the Atlantic was magical. Sean is a fantastic host.', 5, 5, 5, 5, 24, '2025-08-05', '2025-08-05'),
('00000000-0000-0000-0000-000000009005', '00000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000202', '00000000-0000-0000-0000-000000008102', 5, 'The honeymoon yurt exceeded all expectations! The champagne package was a lovely touch. Already planning our return.', 5, 5, 4, 5, 32, '2025-08-09', '2025-08-09'),
('00000000-0000-0000-0000-000000009006', '00000000-0000-0000-0000-000000000004', '00000000-0000-0000-0000-000000000202', '00000000-0000-0000-0000-000000008103', 4, 'Amazing location at the edge of Europe. The dome was comfortable and the views are unbeatable. Slightly tricky to find but worth it!', 4, 5, 4, 4, 15, '2025-08-15', '2025-08-15'),
-- Donegal Coastal Camp reviews
('00000000-0000-0000-0000-000000009007', '00000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000203', '00000000-0000-0000-0000-000000008201', 4, 'Great family campsite with direct beach access. Kids loved the surfing lessons and playground. Good value for money.', 4, 5, 5, 4, 9, '2025-07-07', '2025-07-07'),
('00000000-0000-0000-0000-000000009008', '00000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000203', '00000000-0000-0000-0000-000000008202', 5, 'Perfect surfer spot! Right on the beach and Sean has great local knowledge of the best breaks. Will be back!', 5, 5, 5, 4, 14, '2025-07-14', '2025-07-14'),
('00000000-0000-0000-0000-000000009009', '00000000-0000-0000-0000-000000000004', '00000000-0000-0000-0000-000000000203', '00000000-0000-0000-0000-000000008203', 4, 'Nice campsite with beautiful views. Facilities are basic but clean. The beach is stunning.', 4, 5, 4, 3, 6, '2025-07-22', '2025-07-22'),
-- West Cork Eco Retreat reviews
('00000000-0000-0000-0000-000000009010', '00000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000204', '00000000-0000-0000-0000-000000008301', 5, 'The treehouse is pure magic! Falling asleep to the sound of the forest was unforgettable. Aoife is doing amazing work with sustainability.', 5, 5, 5, 5, 28, '2025-08-06', '2025-08-06'),
('00000000-0000-0000-0000-000000009011', '00000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000204', '00000000-0000-0000-0000-000000008302', 5, 'Best eco-retreat we have ever visited. The farm-to-table dinner was extraordinary. Everything feels considered and sustainable.', 5, 4, 5, 5, 21, '2025-08-13', '2025-08-13'),
('00000000-0000-0000-0000-000000009012', '00000000-0000-0000-0000-000000000004', '00000000-0000-0000-0000-000000000204', '00000000-0000-0000-0000-000000008303', 5, 'Stargazer dome was incredible! Clear skies and amazing telescope. The yoga sessions were a bonus. Truly special place.', 5, 5, 4, 5, 17, '2025-08-20', '2025-08-20');

